<?php
if($page==='nonsellable_release_detail'){
 $id=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT o.*,p.name,p.master_sku,u.name user_name FROM nonsellable_outflows o JOIN products p ON p.id=o.product_id LEFT JOIN users u ON u.id=o.user_id WHERE o.id=?');$q->execute([$id]);$r=$q->fetch();if($r&&$r['type']==='Ready for Sale')echo '<div class="alert info">Ready for Sale is an internal reclassification. Physical quantity did not increase or leave the warehouse. Use Packaging Completion for a linked correction.</div>';if(!$r){echo '<div class="alert danger">Physical release not found.</div>';return;}
 echo '<div class="page-head"><div><a class="back" href="?page=nonsellable&history=all">← Non-Sellable History</a><h1>Restricted Release / Reclassification</h1><p>'.e($r['reference_no']?:'NS-OUT-'.$id).'</p></div>'.badge('Recorded','ok').'</div><div class="batch-banner"><div><span>Product</span><strong>'.e($r['name']).'</strong></div><div><span>Qty Released</span><strong>'.(int)$r['qty'].' pcs</strong></div><div><span>Date</span><strong>'.e($r['txn_date']).'</strong></div><div><span>Processed By</span><strong>'.e($r['user_name']).'</strong></div></div><div class="card"><div class="control-list"><div><span>Master SKU</span><b>'.e($r['master_sku']).'</b></div><div><span>Disposition</span><b>'.e($r['type']).'</b></div><div><span>Remarks</span><b>'.e($r['remarks']).'</b></div></div><h3>Original Entries</h3>';$q=$pdo->prepare('SELECT l.*,n.order_id,n.condition_type FROM nonsellable_release_links l JOIN non_sellable n ON n.id=l.non_sellable_id WHERE l.release_id=?');$q->execute([$id]);$links=$q->fetchAll();foreach($links as $l)echo '<p><a class="btn ghost" href="?page=nonsellable_detail&id='.(int)$l['non_sellable_id'].'">NS-'.(int)$l['non_sellable_id'].' · '.e($l['order_id']).' · '.e($l['condition_type']).' · '.(int)$l['qty'].' pcs</a></p>';if(!$links)echo '<div class="alert info">Legacy release: original-entry linkage was not recorded. This release remains in the product physical balance and has not been assigned to an entry automatically.</div>';echo '</div>';return;
}
echo '<div class="card table-wrap"><div class="card-head"><h3>Restricted Release and Reclassification History</h3></div><table class="table"><tr><th>Date</th><th>Reference</th><th>Product</th><th>Qty Out</th><th>Disposition</th><th>Linkage</th><th></th></tr>';
foreach($pdo->query(history_sql('SELECT o.*,p.name,(SELECT COUNT(*) FROM nonsellable_release_links l WHERE l.release_id=o.id) links FROM nonsellable_outflows o JOIN products p ON p.id=o.product_id ORDER BY o.id DESC LIMIT 500')) as $r)echo '<tr><td>'.e($r['txn_date']).'</td><td>'.e($r['reference_no']?:'NS-OUT-'.$r['id']).'</td><td>'.e($r['name']).'</td><td>'.(int)$r['qty'].'</td><td>'.e($r['type']).'</td><td>'.badge($r['links']?'Linked':'Legacy / Unlinked',$r['links']?'ok':'info').'</td><td><a class="btn ghost sm" href="?page=nonsellable_release_detail&id='.(int)$r['id'].'">View Details</a></td></tr>';echo '</table></div>';
